const state = $getWorkflowStaticData('global');
state.sentAlertIds = state.sentAlertIds || {};

const payload = items[0]?.json || {};
const alerts = Array.isArray(payload.items) ? payload.items : [];

const newAlerts = [];
for (const alert of alerts) {
  if (!alert?.id) continue;
  if (state.sentAlertIds[alert.id]) continue;

  state.sentAlertIds[alert.id] = Date.now();

  const createdAt = alert.created_at || 'unknown_time';
  const severity = (alert.severity || 'medium').toUpperCase();
  const confidence = typeof alert.confidence === 'number'
    ? `${(alert.confidence * 100).toFixed(1)}%`
    : 'N/A';

  const message = [
    `Hazard detected`,
    `Stream: ${alert.stream_name || alert.stream_id || 'unknown_stream'}`,
    `Type: ${alert.type || 'unknown_type'}`,
    `Severity: ${severity}`,
    `Confidence: ${confidence}`,
    `Status: ${alert.status_label || 'unknown_status'}`,
    `Details: ${alert.details || 'No details provided'}`,
    `Time: ${createdAt}`
  ].join('\n');

  newAlerts.push({
    json: {
      alert_id: alert.id,
      message
    }
  });
}

const maxRemember = 5000;
const ids = Object.keys(state.sentAlertIds);
if (ids.length > maxRemember) {
  ids
    .sort((a, b) => state.sentAlertIds[a] - state.sentAlertIds[b])
    .slice(0, ids.length - maxRemember)
    .forEach((id) => delete state.sentAlertIds[id]);
}

return newAlerts;
